/// requests handed to the frame over a bounded channel. Bound only by
/// the instance that holds the store lock.
pub struct RemotePort {
    addr: SocketAddr,
    requests: Receiver<RemoteIncoming>,
    frames: Receiver<SubscriberFrame>,
    stop: Arc<AtomicBool>,
