/// The authenticated device as the host knows it. `scope` in
/// `/info` is the listing parameter, so a device learns its own
/// here, and a page hides what its scope forbids.
fn remote_me(&self, device: &PairedDevice) -> RemoteReply {
    let Some(identity) = self.core.identity() else {
        return RemoteReply::new(
            503,
            self.error_json("no_identity", "the host has no identity yet"),
            true,
        );
    };
    let body = serde_json::json!({
        "device_id": device.id,
        "name": device.name,
        "scope": device.scope,
        "server_id": identity.server_id,
        "server_name": identity.server_name,
    });
    self.envelope(200, &body, true)
}

