:root {
  color-scheme: light dark;
  --bg: #f6f6f4;
  --fg: #1d1d1b;
  --muted: #6a6a64;
  --card: #ffffff;
  --line: #d9d9d3;
  --accent: #0a5fd8;
  --wait: #a35200;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #161615;
    --fg: #ececE6;
    --muted: #9a9a92;
    --card: #1f1f1d;
