* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font: 16px/1.4 -apple-system, system-ui, sans-serif;
}

header {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

header .name {
  font-weight: 600;
}

header .scope,
.meta {
  color: var(--muted);
  font-size: 14px;
}

main {
  max-width: 720px;
  margin: 0 auto;
  padding: 12px 16px 48px;
}

h2 {
  margin: 20px 0 8px;
  font-size: 15px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.row {
  display: block;
  width: 100%;
  margin: 0 0 8px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  color: inherit;
  font: inherit;
  text-align: left;
}

.row:focus-visible,
button:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.row.waiting {
  border-left: 5px solid var(--wait);
}

.row .title {
  font-weight: 600;
}

.waiting-word {
  color: var(--wait);
  font-weight: 600;
}

pre {
  margin: 8px 0;
  padding: 12px;
  overflow-x: auto;
  white-space: pre-wrap;
  word-break: break-word;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  font: 13px/1.4 ui-monospace, Menlo, monospace;
}

textarea {
  display: block;
  width: 100%;
  min-height: 96px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
  color: inherit;
  font: inherit;
}

button {
  padding: 8px 14px;
  border: 1px solid var(--accent);
  border-radius: 8px;
  background: var(--accent);
  color: var(--bg);
  font: inherit;
}

button.plain {
  background: transparent;
  color: var(--accent);
}

.notice {
  margin: 12px 0;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--card);
}

.actions {
  display: flex;
  gap: 8px;
  margin: 8px 0;
}

