fn the_invite_url_carries_everything_in_the_fragment() {
    let identity = identity();
    let mut core = loaded_core();
    core.dispatch(
        AppAction::OpenPairing {
            code: "ABCD2345".into(),
            scope: Scope::Read,
        },
        Clock::at(1_000),
    );
    let window = core.pairing().unwrap().clone();
    let url = crate::core::invite_url(&identity, &window, "192.168.1.9", 43187);
    assert_eq!(
        url,
        format!(
            "https://192.168.1.9:43187/#code=ABCD2345&key={}&id={}",
            identity.spki_sha256, identity.server_id
        )
    );
    assert!(!url.contains('?'), "the query reaches the server");
    let loopback = crate::core::invite_url(&identity, &window, "127.0.0.1", 8443);
    assert!(loopback.starts_with("https://127.0.0.1:8443/#code="));
}

#[test]
fn a_cookie_is_found_by_its_exact_name() {
    use crate::core::{cookie_name, cookie_value};
    let id = uuid::Uuid::nil();
    let name = cookie_name(&id);
    assert_eq!(name, "__Host-sb-00000000-0000-0000-0000-000000000000");
    let header = format!("a=1; {name}=tok; __Host-sb=other; b=2");
    assert_eq!(cookie_value(&header, &name), Some("tok"));
    assert_eq!(cookie_value("__Host-sb=x", &name), None);
    assert_eq!(cookie_value(&format!("{name}="), &name), None);
}

